from math import gcd


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    P = [0] * (n + 1)
    for i in range(n):
        P[i + 1] = P[i] + a[i]

    hull = []
    best_num, best_den = 0, 1

    for j in range(1, n + 1):
        t = j - k
        if t < 0:
            continue

        while len(hull) >= 2:
            u, v = hull[-2], hull[-1]
            if (P[v] - P[u]) * (t - v) >= (P[t] - P[v]) * (v - u):
                hull.pop()
            else:
                break
        hull.append(t)

        lo, hi = 0, len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            c, d = hull[mid + 1], hull[mid]
            if (P[j] - P[c]) * (j - d) > (P[j] - P[d]) * (j - c):
                lo = mid + 1
            else:
                hi = mid

        v = hull[lo]
        num, den = P[j] - P[v], j - v
        if num * best_den > best_num * den:
            best_num, best_den = num, den

    g = gcd(best_num, best_den)
    return [best_num // g, best_den // g]
